CREATE DATABASE IF NOT EXISTS project_management_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE project_management_db;

CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('Admin','Project Manager','Team Member','Client') NOT NULL,phone VARCHAR(30),department VARCHAR(100),designation VARCHAR(100),status ENUM('Active','Inactive') DEFAULT 'Active',avatar VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS team_members (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,department VARCHAR(100),designation VARCHAR(100),joining_date DATE,workload INT DEFAULT 0,performance INT DEFAULT 0,skills JSON,assigned_projects JSON,profile_image_name VARCHAR(255),assigned_tasks INT DEFAULT 0,completed_tasks INT DEFAULT 0,pending_tasks INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS clients (id INT AUTO_INCREMENT PRIMARY KEY,company_name VARCHAR(160) NOT NULL,contact_person VARCHAR(120),email VARCHAR(190),phone VARCHAR(30),address TEXT,status VARCHAR(30) DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,category VARCHAR(100),priority ENUM('Low','Medium','High','Urgent') DEFAULT 'Medium',status ENUM('Not Started','In Progress','On Hold','Completed','Cancelled','Delayed') DEFAULT 'Not Started',start_date DATE,end_date DATE,progress TINYINT UNSIGNED DEFAULT 0,manager_id INT,client_id INT,budget DECIMAL(14,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(manager_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS project_members (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,user_id INT NOT NULL,role_in_project VARCHAR(100),assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(project_id,user_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT,title VARCHAR(200) NOT NULL,description TEXT,assigned_to INT,priority ENUM('Low','Medium','High','Urgent') DEFAULT 'Medium',status ENUM('Pending','In Progress','Under Review','Completed','Reopened','Cancelled') DEFAULT 'Pending',deadline DATETIME,progress TINYINT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS task_checklists (id INT AUTO_INCREMENT PRIMARY KEY,task_id INT NOT NULL,item_text VARCHAR(255) NOT NULL,is_completed BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS milestones (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,title VARCHAR(200),description TEXT,due_date DATE,status VARCHAR(50),progress TINYINT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT,task_id INT,uploaded_by INT,file_name VARCHAR(255),file_path VARCHAR(255),file_type VARCHAR(100),file_size BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS comments (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT,task_id INT,user_id INT,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200),message TEXT,type VARCHAR(50),is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS meetings (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),agenda TEXT,meeting_date DATE,meeting_time TIME,status VARCHAR(50),created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS meeting_participants (id INT AUTO_INCREMENT PRIMARY KEY,meeting_id INT,user_id INT,UNIQUE(meeting_id,user_id),FOREIGN KEY(meeting_id) REFERENCES meetings(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,attendance_date DATE,check_in TIME,check_out TIME,work_hours DECIMAL(5,2),status VARCHAR(50),check_in_latitude DECIMAL(10,7),check_in_longitude DECIMAL(10,7),check_in_accuracy DECIMAL(10,2),check_in_photo VARCHAR(255),check_out_latitude DECIMAL(10,7),check_out_longitude DECIMAL(10,7),check_out_accuracy DECIMAL(10,2),check_out_photo VARCHAR(255),UNIQUE(user_id,attendance_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS daily_reports (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,report_date DATE,today_tasks TEXT,completed_work TEXT,pending_work TEXT,work_hours DECIMAL(5,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS time_logs (id INT AUTO_INCREMENT PRIMARY KEY,task_id INT,user_id INT,start_time DATETIME,end_time DATETIME,total_minutes INT,is_billable BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS budgets (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT,total_budget DECIMAL(14,2),used_budget DECIMAL(14,2),payment_status VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS expenses (id INT AUTO_INCREMENT PRIMARY KEY,project_id INT,title VARCHAR(200),amount DECIMAL(14,2),expense_date DATE,category VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_logs (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(100),module VARCHAR(100),description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);

-- Hashes are generated safely by `python database/seed_demo_users.py`.

CREATE TABLE IF NOT EXISTS module_state (module_key VARCHAR(80) PRIMARY KEY,payload JSON NOT NULL,updated_by INT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);


ALTER TABLE projects ADD COLUMN IF NOT EXISTS manager_name VARCHAR(120), ADD COLUMN IF NOT EXISTS client_name VARCHAR(160), ADD COLUMN IF NOT EXISTS team_members JSON, ADD COLUMN IF NOT EXISTS total_tasks INT DEFAULT 0;

ALTER TABLE users ADD COLUMN IF NOT EXISTS assigned_projects JSON, ADD COLUMN IF NOT EXISTS profile_image_name VARCHAR(255);

ALTER TABLE users ADD COLUMN IF NOT EXISTS joining_date DATE, ADD COLUMN IF NOT EXISTS workload TINYINT UNSIGNED DEFAULT 0, ADD COLUMN IF NOT EXISTS performance TINYINT UNSIGNED DEFAULT 0, ADD COLUMN IF NOT EXISTS skills JSON;

ALTER TABLE users ADD COLUMN IF NOT EXISTS assigned_tasks INT DEFAULT 0, ADD COLUMN IF NOT EXISTS completed_tasks INT DEFAULT 0, ADD COLUMN IF NOT EXISTS pending_tasks INT DEFAULT 0;

ALTER TABLE clients ADD COLUMN IF NOT EXISTS city VARCHAR(120), ADD COLUMN IF NOT EXISTS industry VARCHAR(120), ADD COLUMN IF NOT EXISTS payment_status VARCHAR(40), ADD COLUMN IF NOT EXISTS project_value DECIMAL(14,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS paid_amount DECIMAL(14,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS assigned_projects JSON, ADD COLUMN IF NOT EXISTS notes TEXT, ADD COLUMN IF NOT EXISTS company_logo VARCHAR(255);

CREATE TABLE IF NOT EXISTS calendar_events (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,event_type VARCHAR(80),project_name VARCHAR(200),related_task VARCHAR(200),assigned_to_name VARCHAR(120),event_date DATE NOT NULL,start_time TIME,end_time TIME,priority VARCHAR(30),status VARCHAR(40),reminder VARCHAR(80),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

ALTER TABLE meetings ADD COLUMN IF NOT EXISTS description TEXT, ADD COLUMN IF NOT EXISTS meeting_type VARCHAR(80), ADD COLUMN IF NOT EXISTS project_name VARCHAR(200), ADD COLUMN IF NOT EXISTS client_name VARCHAR(200), ADD COLUMN IF NOT EXISTS end_time TIME, ADD COLUMN IF NOT EXISTS meeting_mode VARCHAR(40), ADD COLUMN IF NOT EXISTS location VARCHAR(255), ADD COLUMN IF NOT EXISTS meeting_link VARCHAR(500), ADD COLUMN IF NOT EXISTS participants JSON, ADD COLUMN IF NOT EXISTS notes JSON;

ALTER TABLE daily_reports ADD COLUMN IF NOT EXISTS report_title VARCHAR(200), ADD COLUMN IF NOT EXISTS project_name VARCHAR(200), ADD COLUMN IF NOT EXISTS task_name VARCHAR(200), ADD COLUMN IF NOT EXISTS work_type VARCHAR(80), ADD COLUMN IF NOT EXISTS work_summary TEXT, ADD COLUMN IF NOT EXISTS blockers TEXT, ADD COLUMN IF NOT EXISTS tomorrow_plan TEXT, ADD COLUMN IF NOT EXISTS start_time TIME, ADD COLUMN IF NOT EXISTS end_time TIME, ADD COLUMN IF NOT EXISTS break_minutes INT DEFAULT 0, ADD COLUMN IF NOT EXISTS productive_hours DECIMAL(5,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS overtime_hours DECIMAL(5,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS task_progress TINYINT UNSIGNED DEFAULT 0, ADD COLUMN IF NOT EXISTS task_status VARCHAR(50), ADD COLUMN IF NOT EXISTS productivity_score TINYINT UNSIGNED DEFAULT 0, ADD COLUMN IF NOT EXISTS productivity_level VARCHAR(40), ADD COLUMN IF NOT EXISTS status VARCHAR(40) DEFAULT 'Submitted', ADD COLUMN IF NOT EXISTS submitted_at DATETIME, ADD COLUMN IF NOT EXISTS reviewed_by VARCHAR(120), ADD COLUMN IF NOT EXISTS reviewer_comment TEXT, ADD COLUMN IF NOT EXISTS attachments JSON, ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;

ALTER TABLE budgets ADD COLUMN IF NOT EXISTS project_name VARCHAR(200), ADD COLUMN IF NOT EXISTS client_name VARCHAR(200), ADD COLUMN IF NOT EXISTS remaining_budget DECIMAL(14,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS profit_loss DECIMAL(14,2) DEFAULT 0, ADD COLUMN IF NOT EXISTS start_date DATE, ADD COLUMN IF NOT EXISTS end_date DATE, ADD COLUMN IF NOT EXISTS notes TEXT;

ALTER TABLE expenses ADD COLUMN IF NOT EXISTS project_name VARCHAR(200), ADD COLUMN IF NOT EXISTS client_name VARCHAR(200), ADD COLUMN IF NOT EXISTS payment_method VARCHAR(80), ADD COLUMN IF NOT EXISTS status VARCHAR(40), ADD COLUMN IF NOT EXISTS notes TEXT, ADD COLUMN IF NOT EXISTS receipt VARCHAR(255);

ALTER TABLE notifications ADD COLUMN IF NOT EXISTS recipient_role VARCHAR(50), ADD COLUMN IF NOT EXISTS recipient_user VARCHAR(120), ADD COLUMN IF NOT EXISTS related_project VARCHAR(200), ADD COLUMN IF NOT EXISTS related_task VARCHAR(200), ADD COLUMN IF NOT EXISTS channels JSON, ADD COLUMN IF NOT EXISTS priority VARCHAR(30), ADD COLUMN IF NOT EXISTS status VARCHAR(40) DEFAULT 'Sent', ADD COLUMN IF NOT EXISTS scheduled_at DATETIME, ADD COLUMN IF NOT EXISTS sender_id INT, ADD COLUMN IF NOT EXISTS sender_name VARCHAR(120), ADD COLUMN IF NOT EXISTS sender_role VARCHAR(50);

CREATE TABLE IF NOT EXISTS backups (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL,type VARCHAR(100) NOT NULL,size VARCHAR(50) DEFAULT '0 MB',status VARCHAR(40) DEFAULT 'Completed',created_by_id INT NULL,created_by VARCHAR(120),storage_location VARCHAR(120),included_data TEXT,restore_count INT DEFAULT 0,last_restored DATETIME NULL,notes TEXT,scheduled_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS restore_history (id INT AUTO_INCREMENT PRIMARY KEY,backup_id INT NOT NULL,restored_by_id INT NULL,restore_type VARCHAR(100) NOT NULL,notes TEXT,status VARCHAR(40) DEFAULT 'Completed',restored_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(backup_id) REFERENCES backups(id) ON DELETE CASCADE,FOREIGN KEY(restored_by_id) REFERENCES users(id) ON DELETE SET NULL);


CREATE TABLE IF NOT EXISTS settings (id INT AUTO_INCREMENT PRIMARY KEY,section VARCHAR(80) NOT NULL UNIQUE,setting_data JSON NOT NULL,updated_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);


ALTER TABLE clients ADD COLUMN IF NOT EXISTS user_id INT NULL;


CREATE TABLE IF NOT EXISTS feedback_responses (id INT AUTO_INCREMENT PRIMARY KEY,feedback_id INT NOT NULL,message TEXT NOT NULL,status_update VARCHAR(50),internal_note TEXT,notify_client BOOLEAN DEFAULT TRUE,responder_id INT NULL,responder_name VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(responder_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS client_feedback (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,message TEXT NOT NULL,client_name VARCHAR(120),company_name VARCHAR(160),client_email VARCHAR(190),project_name VARCHAR(200),category VARCHAR(100),rating TINYINT UNSIGNED,priority VARCHAR(30) DEFAULT 'Medium',status VARCHAR(50) DEFAULT 'Pending',submitted_date DATE,assigned_manager VARCHAR(120),last_response_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
